"""Incremental cohort-retention computation over out-of-order event streams."""

import json
import random


class RetentionAccumulator:
    """Consumes analytics events one at a time in arbitrary order.

    Events are dicts with keys:
      - user_id: hashable
      - type: "signup" | "active"
      - week: int

    Guarantees (order-independent final state):
      * Orphan actives (user not yet signed up) are buffered until the
        signup arrives.
      * Duplicate signups are ignored; the smallest week wins, so the
        result does not depend on arrival order.
      * Duplicate (user_id, week) actives are counted once.

    triangle() may be called at any point and reflects exactly the
    events consumed so far.
    """

    def __init__(self, horizon=6):
        self.horizon = horizon
        # user_id -> smallest signup week seen ("first by week")
        self._signup_week = {}
        # user_id -> set of active weeks (dedupes (user, week) actives,
        # and doubles as the orphan-active buffer pre-signup)
        self._active_weeks = {}

    def process(self, event):
        etype = event["type"]
        uid = event["user_id"]
        week = event["week"]
        if etype == "signup":
            prev = self._signup_week.get(uid)
            if prev is None or week < prev:
                self._signup_week[uid] = week
        elif etype == "active":
            self._active_weeks.setdefault(uid, set()).add(week)
        else:
            raise ValueError(f"unknown event type: {etype!r}")

    def process_all(self, events):
        for e in events:
            self.process(e)

    def triangle(self):
        """Return the retention triangle over events seen so far.

        Format:
          {
            cohort_week: {
              "size": <int cohort size>,
              "retained": [<count active at cohort_week+k for k=1..horizon>],
              "rates": [<retained/size or None>],
            },
            ...
          }
        Cohort weeks are sorted ascending; rates are None where size == 0.
        Serialized output is byte-identical regardless of arrival order.
        """
        size = {}
        retained = {}
        for uid, sw in self._signup_week.items():
            size[sw] = size.get(sw, 0) + 1
            bucket = retained.setdefault(sw, [0] * self.horizon)
            for aw in self._active_weeks.get(uid, ()):
                k = aw - sw
                if 1 <= k <= self.horizon:
                    bucket[k - 1] += 1
        out = {}
        for sw in sorted(size):
            n = size[sw]
            counts = retained[sw]
            out[sw] = {
                "size": n,
                "retained": counts,
                "rates": [(c / n if n else None) for c in counts],
            }
        return out


def batch_retention(events, horizon=6):
    """Batch reference implementation: sort by week, fold sequentially."""
    ordered = sorted(events, key=lambda e: e["week"])
    acc = RetentionAccumulator(horizon)
    acc.process_all(ordered)
    return acc.triangle()


def generate_stream(num_users=1500, seed=5):
    """Generate the canonical event list (unshuffled)."""
    rng = random.Random(seed)
    events = []
    for i in range(num_users):
        uid = f"user_{i}"
        signup_week = rng.randint(0, 9)
        events.append({"user_id": uid, "type": "signup", "week": signup_week})
        for k in range(1, 7):
            if rng.random() < 0.65 ** k:
                events.append(
                    {"user_id": uid, "type": "active", "week": signup_week + k}
                )
    return events


def shuffled_copies(events, num_copies=3, base_seed=100):
    """Return num_copies independently shuffled copies of events."""
    copies = []
    for c in range(num_copies):
        cp = list(events)
        random.Random(base_seed + c).shuffle(cp)
        copies.append(cp)
    return copies


if __name__ == "__main__":
    import time

    stream = generate_stream()
    orders = shuffled_copies(stream)

    ref = batch_retention(stream)
    ref_bytes = json.dumps(ref, sort_keys=True).encode()

    t0 = time.perf_counter()
    for order in orders:
        acc = RetentionAccumulator(horizon=6)
        acc.process_all(order)
        tri = acc.triangle()
        assert json.dumps(tri, sort_keys=True).encode() == ref_bytes, (
            "stream triangle != batch triangle"
        )
    elapsed = time.perf_counter() - t0
    print(f"all {len(orders)} orders match batch; time for "
          f"{len(orders)} x {len(stream)} events: {elapsed:.3f}s")

